@startuml

class Organizer {
  +firstName : string
  +lastName : string
  +email : string
  +postalAddress : string
  +phoneNumber : string
  +password : string
}

class Attendee {
  +firstName : string
  +lastName : string
  +email : string
  +password : string
  +attendanceStatus : string
}

class Event {
  +kind : string
  +startDateTime : datetime
  +endDateTime : datetime
  +occasion : string
}

class Location {
  +name : string
  +address : string
}

class Task {
  +description : string
  +status : string
}

class ChecklistItem {
  +status : string
}

class TaskAssignment {
}

Organizer "1..*" -- "1..*" Event : organizes
Organizer "0..1" -- "0..1" Event : attends
Attendee "0..*" -- "0..*" Event : attends

Organizer "1" -- "*" Event : creates kind of
Location "1" -- "*" Event : at

Organizer "1" -- "*" Task : creates
Event "1" -- "*" ChecklistItem : has
Task "1" -- "*" ChecklistItem : is part of
ChecklistItem "0..1" -- "0..1" Attendee : assigned to
Attendee "0..1" -- "*" TaskAssignment : brings
TaskAssignment "0..*" -- "1" ChecklistItem : links

@enduml

